69	// initRequest 是 init 的输入：{"balances":[...]}。
70	type initRequest struct {
71		Balances []payflow.BalanceInit `json:"balances"`
72	}
73	
74	type errorEnvelope struct {
75		Error struct {
76			Kind    string `json:"kind"`
77			Message string `json:"message"`
78		} `json:"error"`
79	}
80	
81	func failEnvelope(stderr io.Writer, kind, message string) int {
82		env := errorEnvelope{}
83		env.Error.Kind = kind
84		env.Error.Message = message
85		writeJSON(stderr, env)
86		return 1
87	}
88	
89	func failWithError(stderr io.Writer, err error) int {
90		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
91	}
92	
93	func writeJSON(w io.Writer, v any) {
94		data, err := json.MarshalIndent(v, "", "  ")
95		if err != nil {
96			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
97			return
98		}
99		w.Write(data)
100		w.Write([]byte("\n"))
101	}
