103	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
104	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
105		fs := flag.NewFlagSet(name, flag.ContinueOnError)
106		fs.SetOutput(io.Discard)
107		var ledgerPath, inputFile string
108		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
109		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
110		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
111		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
112		return fs, &ledgerPath, &inputFile
113	}
114	
115	func readInput(path string, stdin io.Reader) ([]byte, error) {
116		if path == "" {
117			return io.ReadAll(stdin)
