141		}
142		if err := payflow.CreateLedger(*ledgerPath, req.Balances); err != nil {
143			return failWithError(stderr, err)
144		}
145		writeJSON(stdout, map[string]any{
146			"status":   "initialized",
147			"ledger":   *ledgerPath,
148			"accounts": len(req.Balances),
149		})
150		return 0
151	}
