94				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
95			}
96			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
97				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
98			}
99			if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
100				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
101			}
102			if r.FeeBps < 0 || r.FeeBps > 10000 {
103				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
104			}
105			if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
106				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
107			}
108			if r.Charged != r.Amount+r.Fee {
109				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
110			}
111			if int64(i)+1 != r.Seq {
112				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
113			}
114		}
115	
116		// 校验退款自身的不变式：字段非空、序列连续、引用的结算在退款时点已存在、
117		// 金额与去向与原结算逐字一致、每笔结算最多退回一次、退款编号全局唯一。
118		seenRefund := map[string]bool{}
119		refundedBy := map[string]string{} // 结算编号 -> 首个退回它的退款编号
120		for i, rf := range refunds {
121			if rf.ID == "" {
122				return ledgerError(ErrCorrupt, "refund %d has empty id", i)
123			}
124			if seenRefund[rf.ID] {
125				return ledgerError(ErrCorrupt, "duplicate refund id %q", rf.ID)
126			}
127			seenRefund[rf.ID] = true
128			if rf.SettlementID == "" || rf.Reason == "" {
129				return ledgerError(ErrCorrupt, "refund %q missing settlement_id or reason", rf.ID)
130			}
131			if int64(i)+1 != rf.Seq {
132				return ledgerError(ErrCorrupt, "refund %q sequence gap", rf.ID)
133			}
134			if rf.AfterSeq < 0 || rf.AfterSeq > int64(len(records)) {
135				return ledgerError(ErrCorrupt, "refund %q references settlement outside history (after_seq=%d)", rf.ID, rf.AfterSeq)
136			}
137			var target *Record
138			for j := range records {
139				if records[j].Seq <= rf.AfterSeq && records[j].ID == rf.SettlementID {
140					target = &records[j]
141					break
142				}
143			}
144			if target == nil {
145				return ledgerError(ErrCorrupt, "refund %q references non-existent settlement %q", rf.ID, rf.SettlementID)
146			}
147			if rf.Account != target.Account || rf.Asset != target.Asset ||
148				rf.Amount != target.Amount || rf.Fee != target.Fee || rf.Charged != target.Charged {
149				return ledgerError(ErrCorrupt, "refund %q amount or destination differs from settlement %q", rf.ID, rf.SettlementID)
150			}
151			if rf.Charged <= 0 {
152				return ledgerError(ErrCorrupt, "refund %q has non-positive charged amount", rf.ID)
153			}
154			if other, dup := refundedBy[rf.SettlementID]; dup {
155				return ledgerError(ErrCorrupt, "settlement %q refunded twice: %q and %q", rf.SettlementID, other, rf.ID)
156			}
157			refundedBy[rf.SettlementID] = rf.ID
158		}
159	
160		// 按成功时间交错重放：第 s 笔结算之后落入 after_seq==s 的全部退款
161		// （退款之间按其自身序号；用分桶而非假定 after_seq 单调，以抵抗篡改数据）。
162		// net[k] 为该组合截至当前时点的“净扣款”（扣款增加、退款减少），
163		// 必须始终落在 [0, initial]，且不发生 int64 溢出。
164		buckets := make([][]int, len(records)+1) // after_seq -> refunds 下标
165		for i := range refunds {
166			buckets[refunds[i].AfterSeq] = append(buckets[refunds[i].AfterSeq], i)
167		}
168		net := make(map[balanceKey]int64)
169		for s := range records {
170			r := &records[s]
171			k := balanceKey{r.Account, r.Asset}
172			sum := net[k]
173			if r.Charged > math.MaxInt64-sum {
174				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
175			}
176			sum += r.Charged
177			if sum > initial[k] {
178				return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative during replay", r.ID, r.Account, r.Asset)
179			}
180			net[k] = sum
181	
182			for _, ri := range buckets[int64(s)+1] {
183				rf := &refunds[ri]
184				rk := balanceKey{rf.Account, rf.Asset}
185				cur := net[rk]
186				if rf.Charged > cur {
187					return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
188				}
189				net[rk] = cur - rf.Charged
190			}
191		}
192		// after_seq==0 的退款不可能引用任何已存在结算，前面理应已拒绝；
193		// 此处兜底，任何未被消费的退款都视为顺序损坏。
194		if len(buckets[0]) != 0 {
195			return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
196		}
197	
198		// 交错重放后的末态必须与文件中的最终余额逐组合一致。
199		for k, start := range initial {
200			got := start - net[k]
201			if want, present := final[k]; !present || got != want {
202				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
203			}
204		}
205		for k := range final {
206			if _, ok := initial[k]; !ok {
207				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
208			}
209		}
210		return nil
211	}
212	
213	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
214	func checksumHex(data []byte) string {
215		sum := sha256.Sum256(data)
216		return hex.EncodeToString(sum[:])
217	}
