// 整份报告在同一把账本互斥锁内生成，因而对应同一个完整账本状态，
// 与并发的 Submit/Refund 串行，不会读到半截历史。
func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
	if err := l.beginOp(); err != nil {
		return nil, err
	}
	defer l.endOp()
